<?php require dirname(__DIR__,2).'/app/bootstrap.php';requireAdmin();header('Content-Type: application/json');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verifyCsrf();
$kind=(string)($_POST['kind']??'original');if(!in_array($kind,['original','thumbnail'],true)){http_response_code(422);echo json_encode(['error'=>'Invalid upload kind']);exit;}
$type=(string)($_POST['content_type']??'');$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$size=filter_var($_POST['size']??null,FILTER_VALIDATE_INT);if(!isset($allowed[$type]) || !$size || ($kind==='thumbnail'?($type!=='image/jpeg'||$size>1024*1024):$size>5*1024*1024)){http_response_code(422);echo json_encode(['error'=>'Invalid image type or size']);exit;}
try{$key='products/'.($kind==='thumbnail'?'thumbs/':'').bin2hex(random_bytes(16)).'.'.$allowed[$type];$cmd=s3()->getCommand('PutObject',['Bucket'=>envv('AWS_S3_BUCKET'),'Key'=>$key,'ContentType'=>$type]);$url=(string)s3()->createPresignedRequest($cmd,'+5 minutes')->getUri();echo json_encode(['key'=>$key,'url'=>$url]);}catch(Throwable $e){error_log($e->getMessage());http_response_code(500);echo json_encode(['error'=>'Could not create upload URL']);}
